// Catalog of the ЭЕШ practice mocks imported from MockExmps. Client-safe metadata only:
// no question text, answers or explanations live here. Generated by scripts/build-entrance-mocks.mjs.
import { entranceCatalog } from "./catalog-data.ts";
import { ENTRANCE_SUBJECT_ORDER, type EntranceSubject } from "./subjects.ts";
export * from "./subjects.ts";

export type EntranceMeta = {
  slug: string;
  subject: EntranceSubject;
  year: number;
  form: string;
  title: string;
  durationMinutes: number;
  points: number;
  questionCount: number;
  groupCount: number;
  description: string;
};
const data = entranceCatalog as unknown as { generatedAt: string; subjects: Record<EntranceSubject, { label: string; title: string; years: number[] }>; mocks: EntranceMeta[] };
export const entranceMocks: EntranceMeta[] = data.mocks;
const bySlug = new Map(entranceMocks.map(mock => [mock.slug, mock]));

export function findEntranceMeta(slug: string): EntranceMeta | undefined {
  return bySlug.get(slug);
}
export function isEntranceSlug(slug: string): boolean {
  return bySlug.has(slug);
}
export function entranceSubjectOf(slug: string): EntranceSubject | null {
  return findEntranceMeta(slug)?.subject ?? null;
}
export function mocksFor(subject: EntranceSubject): EntranceMeta[] {
  return entranceMocks.filter(mock => mock.subject === subject);
}
export function entranceYears(subject: EntranceSubject): number[] {
  return [...new Set(mocksFor(subject).map(mock => mock.year))].sort((a, b) => b - a);
}
export function entranceCounts(): Record<EntranceSubject, number> {
  return Object.fromEntries(ENTRANCE_SUBJECT_ORDER.map(subject => [subject, mocksFor(subject).length])) as Record<EntranceSubject, number>;
}
export const entranceTotal = entranceMocks.length;
export function entranceSlugs(): string[] {
  return entranceMocks.map(mock => mock.slug);
}
/** The mocks for one subject/year, in printed form order. */
export function mocksForYear(subject: EntranceSubject, year: number): EntranceMeta[] {
  return mocksFor(subject).filter(mock => mock.year === year).sort((a, b) => a.form.localeCompare(b.form, "en", { numeric: true }));
}
